import { BaseUrl, InquiryOptions } from './interfaces';
/**
 * Wraps the Inquiry iframe with embedded modal event / action handling.
 */
export default class Client {
    private readonly options;
    private _isLoading;
    private _isOpen;
    private containerId;
    private containerElement;
    private containerParent;
    private personaCSS;
    private globalCSS;
    private loadingElement;
    private iframeElement;
    private unsubscribeFromEvents;
    private preferredDimensions;
    /**
     * Creates an iframe that loads all static assets needed for the Persona
     * Inquiry flow, but does not initiate the flow itself. This is intended to
     * populate the browser cache to speed up subsequent loads.
     */
    static preload(host?: InquiryOptions['host']): Promise<void>;
    constructor(options: InquiryOptions);
    render(): void;
    open(): void;
    cancel(force: boolean): void;
    destroy(): void;
    private onLoad;
    private onReady;
    private onComplete;
    private onCancel;
    private handleResize;
    get isLoading(): boolean;
    get isOpen(): boolean;
    /**
     * Gets the base URL for iframe communication. If the URL does not match the
     * iframe origin, messages posted from persona-verify will be ignored by
     * persona-web.
     */
    get baseUrl(): BaseUrl | string;
}
